function out = arm_C(q, qd, P)
%ARM_C Coriolis matrix C(q,qd) (Christoffel)
%% AUTO-GENERATED by python/rehab_arm/dynamics_derive.py (SymPy Euler-Lagrange).
%% P = [L1 L2 c1 c2 m1 m2 mp r1 r2 g]
%#codegen
q1 = q(1); q2 = q(2); q3 = q(3);
qd1 = qd(1); qd2 = qd(2); qd3 = qd(3);
L1 = P(1); L2 = P(2); c1 = P(3); c2 = P(4); m1 = P(5); m2 = P(6); mp = P(7); r1 = P(8); r2 = P(9); g = P(10); 
out = zeros(3,3);
t0 = 12*mp;
t1 = L1.*L2;
t2 = t1.*sin(q3);
t3 = c2.*m2;
t4 = 12*t3;
t5 = 2*q2;
t6 = t1.*sin(q3 + t5);
t7 = t0.*t6 + t4.*t6;
t8 = L2.^2;
t9 = sin(2*q3 + t5);
t10 = m2.*t9;
t11 = t10.*t8;
t12 = r2.^2;
t13 = t8.*t9;
t14 = c2.^2.*t11;
t15 = t0.*t13 - 3*t10.*t12 + t11 + 12*t14;
t16 = L1.^2;
t17 = sin(t5);
t18 = m1.*t17;
t19 = t16.*t18;
t20 = r1.^2;
t21 = t16.*t17;
t22 = 12*t21;
t23 = c1.^2.*t19;
t24 = 24*t6;
t25 = 6*t21;
t26 = 6*mp;
t27 = -3*m2.*t12.*t9/2 + t11/2 + t13.*t26 + 6*t14;
t28 = -3*m1.*t17.*t20/2 + m2.*t25 + mp.*t25 + t19/2 + 6*t23 + t27 + t7;
t29 = qd1/12;
t30 = 6*t3;
t31 = t2.*t26 + t2.*t30 + t26.*t6 + t27 + t30.*t6;
t32 = t2.*(mp + t3);
out(1,1) = -qd2.*(m2.*t22 + mp.*t22 + mp.*t24 + t15 - 3*t18.*t20 + t19 + 12*t23 + t24.*t3)/24 - qd3.*(t0.*t2 + t15 + t2.*t4 + t7)/24;
out(1,2) = -t28.*t29;
out(1,3) = -t29.*t31;
out(2,1) = t28.*t29;
out(2,2) = -qd3.*t32;
out(2,3) = t32.*(-qd2 - qd3);
out(3,1) = t29.*t31;
out(3,2) = qd2.*t32;
out(3,3) = 0;
end
